std::thread_local! { static POSTERIOR_COUNTS: std::cell::Cell<[u64; 2]> = const { std::cell::Cell::new([0; 2]) }; }

#[inline(always)]
pub fn posterior4(&self, n: [u64; 4], d: [u64; 4]) -> Option<[u64; 4]> {
    let result = self.batches.try_nonzero4(n, d);
    #[cfg(khc_compact_counts)]
    POSTERIOR_COUNTS.with(|counts| {
        let mut current = counts.get();
        let index = usize::from(result.is_none());
        current[index] = current[index].checked_add(1).expect("posterior count overflow");
        counts.set(current);
    });
    result
}

