fn try_posterior_batch(
    &self, prediction: &Prediction, bit: bool, table: &exact_kt::KtTable, upper: usize,
) -> Option<[u64; 4]> {
    let mut n = [0; 4];
    let mut d = [0; 4];
    for lane in 0..4 {
        let level = upper.checked_sub(lane)?;
        let node = self.nodes.get(*prediction.indexes.get(level)?)?;
        if node.weight > Q { return None; }
        let pk = if bit {
            Q.checked_sub(*prediction.kt.get(level)?)?
        } else { *prediction.kt.get(level)? };
        let child = if bit {
            Q.checked_sub(*prediction.zero.get(level + 1)?)?
        } else { *prediction.zero.get(level + 1)? };
        let ceiling = cached_ceiling(
            node.weight, *prediction.weights.get(level)?, pk, child,
            *prediction.zero.get(level)?, (prediction.remainder >> level) & 1 != 0, bit,
        ).ok()?;
        probability(pk).ok()?;
        n[lane] = node.weight.checked_mul(pk)?;
        d[lane] = ceiling;
    }
    table.posterior4(n, d)
